import json, os, platform, shutil, subprocess
from pathlib import Path
out={'schema':'hepta-main-readonly-host-identity-v1','host_alias':'main','uname':list(platform.uname()),'machine':platform.machine(),'system':platform.system(),'uid':os.getuid(),'euid':os.geteuid(),'tools':{}}
for name in ('git','cargo','rustc','just','cargo-nextest','bazel','python3'):
 p=shutil.which(name)
 out['tools'][name]={'selected_path':p,'resolved_path':str(Path(p).resolve()) if p else None}
if Path('/usr/bin/sw_vers').is_file():
 r=subprocess.run(['/usr/bin/sw_vers'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=False)
 out['sw_vers']={'argv':['/usr/bin/sw_vers'],'exit_code':r.returncode,'stdout':r.stdout.decode(),'stderr':r.stderr.decode()}
out.update({'read_only':True,'source_modified':False,'build_or_tests_started':False,'tools_installed':False})
print(json.dumps(out,sort_keys=True,ensure_ascii=False))
